arguments.command:
curl -s https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" --data "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print(d); sys.exit()
for u in d.get('members',[]):
    name=(u.get('profile',{}).get('real_name') or u.get('name') or '').lower()
    if 'leo' in name or 'park' in name:
        print(u['id'], repr(u.get('profile',{}).get('real_name')), u.get('name'))
"

